insert ignore into site_media_reference (media_id, owner_type, owner_id, reference_role, field_key, sort_no) select media_id, 'CREDENTIAL_REVISION', @site_credential_revision_id, 'ATTACHMENT', convert(0x2fe8bdafe4bbb6e89197e4bd9ce69d83e8af81e4b9a62fe5b9b3e8a18ce695b0e5ad97e998b2e6b19be6b3b5e7ab99e4b880e4bd93e58c96e5b9b3e58fb056312e302e706466 using utf8mb4), 0 from site_media where source_legacy_key = convert(0x2fe8bdafe4bbb6e89197e4bd9ce69d83e8af81e4b9a62fe5b9b3e8a18ce695b0e5ad97e998b2e6b19be6b3b5e7ab99e4b880e4bd93e58c96e5b9b3e58fb056312e302e706466 using utf8mb4);
